// Profile for testing
const testProfile: CitizenProfile = {
  residenceState: 'Andhra Pradesh',
  annualIncome: 180000,
  age: 35,
  isFarmer: true,
  isBusinessOwner: true,
  isBPL: true,
  hasHouseDamage: true,
  propertyDamageType: 'severe',
};

async function runMultilingualSuite() {
  console.log('===============================================================');
  console.log('  JANSETU 13-LANGUAGE MULTILINGUAL INTENT VALIDATION SUITE');
  console.log('===============================================================\n');

  let totalTests = 0;
  let passedTests = 0;
  let failedTests = 0;
  const failures: { schemeId: string; lang: string; prompt: string; reason: string }[] = [];

  for (const spec of SCHEME_SPECS) {
    for (const lang of LANGUAGES) {
      const prompts = spec.prompts[lang];
      if (!prompts || prompts.length < 3) {
        console.error(`Missing prompts for scheme ${spec.id} in language ${lang}`);
        continue;
      }

      for (let pIdx = 0; pIdx < prompts.length; pIdx++) {
        totalTests++;
        const prompt = prompts[pIdx];

        // 1. Classify intent
        const classification = classifyLifeEvent(prompt);

        // LifeEvent category or primaryIntent match
        const matchedLifeEvent = LIFE_EVENTS.find((e) => e.id === classification.primaryIntent);
        const resolvedCategory = matchedLifeEvent?.category || classification.primaryIntent;

        const isCategoryCorrect =
          resolvedCategory === spec.expectedCategory ||
          classification.primaryIntent === spec.expectedCategory ||
          (spec.expectedCategory === 'housing' && resolvedCategory === 'housing') ||
          (spec.expectedCategory === 'disaster' && resolvedCategory === 'disaster') ||
          (spec.expectedCategory === 'business' && (resolvedCategory === 'business' || resolvedCategory === 'employment')) ||
          (spec.expectedCategory === 'employment' && (resolvedCategory === 'employment' || resolvedCategory === 'business'));

        if (!isCategoryCorrect || classification.requiresClarification) {
          failedTests++;
          failures.push({
            schemeId: spec.id,
            lang,
            prompt,
            reason: `Category mismatch: Expected '${spec.expectedCategory}', got '${resolvedCategory}' (Intent: ${classification.primaryIntent}, Clarification: ${classification.requiresClarification})`,
          });
          continue;
        }

        // 2. Relevance Matching & Ranking
        if (!matchedLifeEvent) {
          failedTests++;
          failures.push({
            schemeId: spec.id,
            lang,
            prompt,
            reason: `No matched LifeEvent found for intent '${classification.primaryIntent}'`,
          });
          continue;
        }

        const effectiveProfile: CitizenProfile = {
          ...testProfile,
          propertyState: 'Andhra Pradesh',
          businessState: 'Andhra Pradesh',
          agricultureState: 'Andhra Pradesh',
          employmentState: 'Andhra Pradesh',
          ...(classification.extractedContext || {}),
        };
        const { recommendations } = findRelevantServices(effectiveProfile, matchedLifeEvent, prompt);
        const topRec = recommendations[0];
        const isTargetInTop3 = recommendations.slice(0, 3).some((r) => r.serviceId === spec.id);

        if (!isTargetInTop3) {
          failedTests++;
          failures.push({
            schemeId: spec.id,
            lang,
            prompt,
            reason: `Target scheme '${spec.id}' not in top 3 recommendations (Top 1: ${topRec?.serviceId || 'none'})`,
          });
          continue;
        }

        passedTests++;
      }
    }
  }

  console.log(`\n--- Multilingual Prompt Tests: ${passedTests} / ${totalTests} Passed ---`);

  // Run Negative & Unrelated Tests
  console.log('\n--- Running Negative & Unrelated Query Tests ---');
  const negativeQueries = [
    'what is the weather today in Hyderabad',
    'play latest telugu film songs',
    'recipe for chicken biryani',
    'current score of india vs australia cricket match',
    'tell me a funny joke',
    'how to book movie tickets online',
    'good morning have a nice day',
    'what is the capital of France',
  ];

  let negPassed = 0;
  for (const nq of negativeQueries) {
    totalTests++;
    const res = classifyLifeEvent(nq);
    if (res.primaryIntent === 'other' || res.requiresClarification) {
      negPassed++;
      passedTests++;
    } else {
      failedTests++;
      failures.push({
        schemeId: 'NEGATIVE_TEST',
        lang: 'en',
        prompt: nq,
        reason: `Expected 'other' / requiresClarification, got '${res.primaryIntent}'`,
      });
    }
  }
  console.log(`Negative Queries: ${negPassed} / ${negativeQueries.length} Passed`);

  // Run Scheme Confusion & Isolation Tests
  console.log('\n--- Running Scheme Confusion & Cross-Domain Isolation Tests ---');
  const confusionTests = [
    {
      name: 'Crop damage from heavy rain -> must match agriculture/disaster, NOT PM-KISAN or education',
      prompt: 'Heavy rain destroyed my cotton crop, how to claim crop loss compensation?',
      mustNotBeCategory: 'education',
      expectedTarget: 'pm_fasal_bima_yojana',
    },
    {
      name: 'Father passed away -> must match death certificate / legal heir, NOT healthcare or business',
      prompt: 'My father passed away last week, what government certificates do I need to obtain?',
      mustNotBeCategory: 'healthcare',
      expectedTarget: 'death_certificate_registration',
    },
    {
      name: 'Want to start a tea shop -> must match MUDRA / PM SVANidhi, NOT PMAY or agriculture',
      prompt: 'I want to start a small tea stall and need a collateral-free micro loan of ₹50,000.',
      mustNotBeCategory: 'agriculture',
      expectedTarget: 'pm_mudra_yojana',
    },
    {
      name: 'Need hospital surgery -> must match Ayushman Bharat / healthcare, NOT bereavement',
      prompt: 'My mother needs urgent knee surgery and hospital admission with cashless health insurance.',
      mustNotBeCategory: 'bereavement',
      expectedTarget: 'pmjay_ayushman_bharat',
    },
    {
      name: 'Lost job in village -> must match VB-G RAM G / DDU-GKY, NOT CGTMSE',
      prompt: 'I lost my daily wage work in my village, need 100 days unskilled manual work under job card.',
      mustNotBeCategory: 'business',
      expectedTarget: 'vb_gram_g_rural_employment',
    },
    {
      name: 'Solar panels on roof -> must match PM Surya Ghar, NOT disaster reconstruction',
      prompt: 'I want to install 3kW solar panels on my rooftop to get 300 units free electricity.',
      mustNotBeCategory: 'disaster',
      expectedTarget: 'pm_surya_ghar_muft_bijli',
    },
    {
      name: 'House destroyed by cyclone -> must match disaster reconstruction / SDRF, NOT PM Surya Ghar',
      prompt: 'Cyclone storm completely collapsed my pucca house, need emergency reconstruction relief.',
      mustNotBeCategory: 'financial_assistance',
      expectedTarget: 'disaster_house_reconstruction',
    },
    {
      name: 'Solar pump for agriculture -> must match PM-KUSUM, NOT PM Surya Ghar',
      prompt: 'Need solar pump subsidy for agricultural farm irrigation tube well.',
      mustNotBeCategory: 'disaster',
      expectedTarget: 'pm_kusum_solar_pump',
    },
  ];

  let confusionPassed = 0;
  for (const ct of confusionTests) {
    totalTests++;
    const res = classifyLifeEvent(ct.prompt);
    const lifeEvent = LIFE_EVENTS.find((e) => e.id === res.primaryIntent);
    const cat = lifeEvent?.category || res.primaryIntent;

    if (cat === ct.mustNotBeCategory) {
      failedTests++;
      failures.push({
        schemeId: 'CONFUSION_TEST',
        lang: 'en',
        prompt: ct.prompt,
        reason: `Confusion test failed: Classified into forbidden category '${ct.mustNotBeCategory}'`,
      });
      continue;
    }

    if (lifeEvent) {
      const effectiveProfile: CitizenProfile = {
        ...testProfile,
        propertyState: 'Andhra Pradesh',
        businessState: 'Andhra Pradesh',
        agricultureState: 'Andhra Pradesh',
        employmentState: 'Andhra Pradesh',
        ...(res.extractedContext || {}),
      };
      const { recommendations } = findRelevantServices(effectiveProfile, lifeEvent, ct.prompt);
      const isExpectedFound = recommendations.some((r) => r.serviceId === ct.expectedTarget);
      if (!isExpectedFound) {
        failedTests++;
        failures.push({
          schemeId: 'CONFUSION_TEST',
          lang: 'en',
          prompt: ct.prompt,
          reason: `Expected target '${ct.expectedTarget}' not found in recommendations.`,
        });
        continue;
      }
    }

    confusionPassed++;
    passedTests++;
  }
  console.log(`Confusion & Isolation Tests: ${confusionPassed} / ${confusionTests.length} Passed`);

  // Run Code-Mixed / Romanized Tests (Tanglish, Hinglish)
  console.log('\n--- Running Romanized / Code-Mixed Tests ---');
  const codeMixedTests = [
    { prompt: 'meri fasal kharab ho gayi hai baarish se fasal bima chahiye', target: 'pm_fasal_bima_yojana' },
    { prompt: 'naa illu cyclone valla koolipoyindi government saayam kaavali', target: 'disaster_house_reconstruction' },
    { prompt: 'rooftop par solar lagwana hai pm surya ghar subsidy ke liye', target: 'pm_surya_ghar_muft_bijli' },
    { prompt: 'dukana kosam mudra loan kavali collateral lekunda', target: 'pm_mudra_yojana' },
    { prompt: 'pita ji ke swargwas ke baad legal heir certificate kaise banwaye', target: 'legal_heir_family_certificate' },
    { prompt: 'hospital lo surgery kosam ayushman card cashless treatment kavali', target: 'pmjay_ayushman_bharat' },
    { prompt: 'village lo 100 days work job card kavali rozgar guarantee kosam', target: 'vb_gram_g_rural_employment' },
    { prompt: 'bank me zero balance jan dhan account kholna hai rupay card ke saath', target: 'pmjdy_financial_inclusion' },
  ];

  let codeMixedPassed = 0;
  for (const cm of codeMixedTests) {
    totalTests++;
    const res = classifyLifeEvent(cm.prompt);
    const lifeEvent = LIFE_EVENTS.find((e) => e.id === res.primaryIntent);
    if (!lifeEvent) {
      failedTests++;
      failures.push({ schemeId: 'CODE_MIXED', lang: 'romanized', prompt: cm.prompt, reason: `Unclassified` });
      continue;
    }
    const effectiveProfile: CitizenProfile = {
      ...testProfile,
      propertyState: 'Andhra Pradesh',
      businessState: 'Andhra Pradesh',
      agricultureState: 'Andhra Pradesh',
      employmentState: 'Andhra Pradesh',
      ...(res.extractedContext || {}),
    };
    const { recommendations } = findRelevantServices(effectiveProfile, lifeEvent, cm.prompt);
    const hasTarget = recommendations.slice(0, 3).some((r) => r.serviceId === cm.target);
    if (hasTarget) {
      codeMixedPassed++;
      passedTests++;
    } else {
      failedTests++;
      failures.push({ schemeId: 'CODE_MIXED', lang: 'romanized', prompt: cm.prompt, reason: `Target ${cm.target} not in top 3` });
    }
  }
  console.log(`Code-Mixed Tests: ${codeMixedPassed} / ${codeMixedTests.length} Passed`);

  console.log('\n===============================================================');
  console.log(`FINAL RESULTS: ${passedTests} / ${totalTests} TESTS PASSED (${Math.round((passedTests / totalTests) * 100)}%)`);
  if (failedTests > 0) {
    console.error(`❌ Total Failures: ${failedTests}`);
    require('fs').writeFileSync('scripts/all_failures.json', JSON.stringify(failures, null, 2), 'utf8');
    for (const f of failures.slice(0, 10)) {
      console.error(`  - [${f.schemeId}] [${f.lang}] "${f.prompt}": ${f.reason}`);
    }
    process.exit(1);
  } else {
    console.log(`✅ 100% OF TESTS PASSED! ZERO DEFECTS ACROSS ALL 13 INDIC LANGUAGES!`);
  }
  console.log('===============================================================\n');
}

runMultilingualSuite();
